<?php

namespace Agent\AgentBundle\Repository;

use Doctrine\ORM\EntityRepository;

/**
 * NewsRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class NewsRepository extends EntityRepository {

    //recherche des sites fournies par  localité  sur la période
    public function newsActif() {

        $today = new \DateTime();
        $today = $today->format('Y-m-d h:m');


        $QueryBuilder = $this->getEntityManager()->createQueryBuilder();
        $Query = $QueryBuilder
                ->select('n')
                ->from('AgentBundle:News', 'n')
                ->Where('n.debut <= :today')
                ->andWhere('n.fin >= :today')
                ->setParameter('today', $today)
                ->orderBy('n.id', 'DESC')
                ->getQuery()
                ->getResult()
        ;
        return $Query;
    }

}
